def number_to_words(n):
    if type(n) is not int:
        raise ValueError("Input must be an int")
    if n < 0 or n > 999_999_999:
        raise ValueError("Input out of range")
    if n == 0:
        return "zero"
    units = ["zero","one","two","three","four","five","six","seven","eight","nine","ten","eleven","twelve","thirteen","fourteen","fifteen","sixteen","seventeen","eighteen","nineteen"]
    tens = ["","","twenty","thirty","forty","fifty","sixty","seventy","eighty","ninety"]
    def sub_thousand(num):
        parts = []
        hundreds = num // 100
        if hundreds:
            parts.append(units[hundreds] + " hundred")
            num %= 100
        if num:
            if num < 20:
                parts.append(units[num])
            else:
                t = num // 10
                u = num % 10
                if u:
                    parts.append(tens[t] + "-" + units[u])
                else:
                    parts.append(tens[t])
        return " ".join(parts)
    million = n // 1_000_000
    thousand = (n // 1_000) % 1000
    rest = n % 1000
    words = []
    if million:
        words.append(sub_thousand(million) + " million")
    if thousand:
        words.append(sub_thousand(thousand) + " thousand")
    if rest:
        words.append(sub_thousand(rest))
    return " ".join(words)

